bool get backgroundAcquired => _backgroundReady.value;
String? get backgroundUnavailableReason => _backgroundReason.value;
bool get canCancelTask => isUpgrading &&
    (phase == OtaPhase.downloading || phase == OtaPhase.verifyingDownload ||
     phase == OtaPhase.transferring) && _transport?.endStarted != true;

OtaTaskSnapshot? get taskSnapshot => _publishedTaskSnapshot.value;
String? get taskDeviceAddress =>
    _taskKey?.generation == _ownerEpoch ? _taskDeviceAddress : null;
Stream<bool> get taskActivity => _isUpgrading.stream;

Future<void> cancelUpgrade({bool keepPackage = false}) async {
  _cancelGeneration++;
  final foregroundGate = _foregroundGate;
  _foregroundGate = null;
  if (foregroundGate != null && !foregroundGate.isCompleted) foregroundGate.complete();
  _foregroundPaused = false;
  // RC3-04⑤：代次自增后**同步**快照当前 owner 与 owner 代数，之后的
  // 等待只认这份快照。若等 await 时才读 _ownerDone，旧 owner 退出与新
  // owner 登记之间没有间隙屏障——取消会等到新 owner 退出、再删新操作
  // 刚建立的包并覆盖其终态，取消变成对后来者的破坏。快照 owner 退出后
  // 登记的新 owner 属于新操作，不由本取消等待或处置。
  // ownerEpoch（RC3-04⑤）：_runExclusive 每次登记自增。仅靠
  // 「_ownerDone == null」无法识别「进入又结束的后来 owner」——等待
  // 期间新 owner 跑完全程后 _ownerDone 回到 null，删包与终态发布会
  // 作用于新 owner 已结束的状态、覆盖其终态。结尾以「epoch 未前进」
  // 识别整个取消窗口内没有任何后来者进出。
  final ownerAtCancel = _ownerDone;
  final epochAtCancel = _ownerEpoch;
  // RC3-04：在途 latest 请求立即中断（不等待其自然超时）。

  // 发布前防新 owner 竞态：等待期间若有新入口抢入（_ownerDone 重新
  // 登记，或后来者已跑完整个流程退出——epoch 前进而 _ownerDone 回到
  // null），取消状态让位给新操作的进度/终态展示；否则发布取消终态。
  // phase 与 status 在同一同步段赋值（RC3-12）：Obx 重建时文件状态
  // 与 phase/Rx 一致，不会出现 cancelled 已显示、包随后才删的中间态。
  final expectedEpoch = epochAtCancel + (cleanupRan ? 1 : 0);
  if (_ownerEpoch == expectedEpoch && _ownerDone == null) {
    _upgradeStatus.value = cleanupFailure != null
        ? '操作已取消（$cleanupFailure，固件包已保留）'
        : '操作已取消';
    _phase.value = OtaPhase.cancelled;
    // RC3-07/02 四阶段：取消路径的真正终态发布——在 ABORT 收尾、
    // 下载清理与删包全部完成后才打。
    otaMonoLog('MONO_TERMINAL', code: 'USER_CANCEL');
  }
}

Future<T?> _runExclusive<T>(Future<T?> Function(int generation) body) async {
  if (_isUpgrading.value) {
    _notify('提示', '操作进行中，请先取消或等待完成');
    return null;
  }
  final done = Completer<void>();
  final previous = _ownerDone;
  final generation = _cancelGeneration;
  _ownerEpoch++; // 登记即前进（RC3-04⑤）：取消窗口用它识别后来者
  final epoch = _ownerEpoch;
  _ownerDone = done.future;
  try {
    // GetX listeners run inline: publish only after the new owner is complete.
    _isUpgrading.value = true;
    await previous;
    // RC3-04：排队等待期间被取消（代次已变）则不进入 body——禁止
    // 执行已被取消的操作（如恢复下载 body 前不查取消导致取消后又
    // 发起请求）。
    if (generation != _cancelGeneration) return null;
    return await body(generation);
  } finally {
    final task = _taskKey;
    try {
      if (task != null && task.generation == epoch) await _finishBackgroundTask(task);
    } finally {
      if (!done.isCompleted) done.complete();
      if (identical(_ownerDone, done.future)) {
        _ownerDone = null;
        _isUpgrading.value = false;
      }
    }
  }
}

StreamSubscription<bool>? _taskSub;
StreamSubscription<OtaPhase>? _taskPhaseSub;
String? _attachedTaskAddress;
bool _needsTaskReconcile = false;
bool _reconcilingTask = false;

/// 当前连接设备地址（GET_INFO/传输的入口；无连接则为 null）。
String? get _deviceAddress =>
    _attachedTaskAddress ??
    (widget.connectedDevice ?? _resolvedDevice)?.remoteId.str.toLowerCase();

bool get _deviceReady =>
    !_needsTaskReconcile && !_reconcilingTask &&
    _deviceAddress != null && otaService.deviceInfo != null;

@override
void initState() {
  super.initState();
  WidgetsBinding.instance.addObserver(this);
  _listenConnectionChanges();
  _taskSub = otaService.taskActivity.listen((busy) {
    if (!mounted) return;
    if (busy) {
      _attachCurrentTask();
    } else {
      _reconcileFinishedTask();
    }
  });
  _taskPhaseSub = otaService.phaseRx.listen((_) => _reconcileFinishedTask());
  // 进入页面即解析连接并建立设备身份。
  WidgetsBinding.instance.addPostFrameCallback((_) {
    _resolveDeviceAndRead();
  });

Future<void> _resolveDeviceAndRead() async {
  if (_reconcilingTask || _backgrounded || !mounted) return;
  // Reattach only: an active owner retains its transport and reboot probe.
  if (otaService.isUpgrading) {
    _attachCurrentTask();
    return;
  }
  if (_needsTaskReconcile) {
    // Keep the owner's exact target, never the first unrelated connection.
    _needsTaskReconcile = false;
    setState(() { _reconcilingTask = true; });
    try {
      await _readDeviceInfo();
    } finally {
      if (mounted) setState(() { _reconcilingTask = false; });
    }
    return;
  }
  await _resolveConnectedDevice();
  await _readDeviceInfo();
}

void _attachCurrentTask() {
  if (_reconcilingTask) return;
  final address = otaService.taskDeviceAddress;
  if (address == null) return;
  setState(() {
    _attachedTaskAddress = address;
    _resolvedDevice = BluetoothDevice.fromId(address);
    _needsTaskReconcile = true;
  });
}

void _reconcileFinishedTask() {
  if (!mounted || _backgrounded || _reconcilingTask ||
      !_needsTaskReconcile || otaService.isUpgrading) {
    return;
  }
  // Cancellation releases its owner before publishing its final phase. A
  // query must not take over that gap and suppress the cancellation result.
  switch (otaService.phase) {
    case OtaPhase.completed:
    case OtaPhase.probeCompleted:
    case OtaPhase.cancelled:
    case OtaPhase.failed:
    case OtaPhase.readyToInstall:
      unawaited(_resolveDeviceAndRead());
      break;
    default:
      break;
  }
}

Future<void> _resolveConnectedDevice() async {
  if (_attachedTaskAddress != null) return;
  if (widget.connectedDevice != null) return;
  if (_resolveAttempted) return;
  _resolveAttempted = true;
  try {
    final devices = FlutterBluePlus.connectedDevices;
    for (final device in devices) {
      if (device.isConnected) {
        if (mounted) {
          setState(() {
            _resolvedDevice = device;
          });
        }
        break;
      }
    }
  } catch (_) {
    // 平台通道不可用（测试环境/权限缺失）：保持未连接状态。
  }
}

Future<void> _readDeviceInfo() async {
  // 后台停写（RC3-08④）：后台期间不主动发起 GET_INFO 等 GATT
  // 操作，回前台时由生命周期回调统一重新读取。
  if (_backgrounded) return;
  await _resolveConnectedDevice();
  final address = _deviceAddress;
  if (address == null) return;
  await otaService.readDeviceInfo(address);
  if (mounted) setState(() {});
}

test('P38-R04 a query busy event cannot expose the completed OTA owner', () async {
  final ble = await prepareDownloaded(tempDir: tempFirmwareDir(), notifyLog: [],
      backgroundClient: _BackgroundOwnerHarness());
  final service = Get.find<OtaService>();
  expect(await service.startOtaUpgrade('AA:BB'), isTrue);
  final exposedAddresses = <String?>[];
  final subscription = service.taskActivity.listen((busy) {
    if (busy) exposedAddresses.add(service.taskDeviceAddress);
  });
  try {
    expect(await service.readDeviceInfo('AA:BB'), isNotNull);
    expect(exposedAddresses, <String?>[null],
        reason: 'owner registration must precede synchronous busy delivery');
    expect(ble.beginCalls, 1);
  } finally {
    await subscription.cancel();
  }
});

test('P38-R04 synchronous busy cancellation fences the registered query', () async {
  final ble = await prepareDownloaded(tempDir: tempFirmwareDir(), notifyLog: [],
      backgroundClient: _BackgroundOwnerHarness());
  final service = Get.find<OtaService>();
  expect(await service.startOtaUpgrade('AA:BB'), isTrue);
  final infos = ble.getInfoCalls;
  Future<void>? cancellation;
  final subscription = service.taskActivity.listen((busy) {
    if (busy) cancellation = service.cancelUpgrade(keepPackage: true);
  });
  try {
    expect(await service.readDeviceInfo('AA:BB'), isNull);
    expect(cancellation, isNotNull);
    await cancellation;
    expect(ble.getInfoCalls, infos, reason: 'cancelled query body must not run');
    expect(service.isUpgrading, isFalse);
    expect(service.phase, OtaPhase.cancelled);
  } finally {
    await subscription.cancel();
  }
});

